export function roundTuning(round){const r=Math.max(1,Math.floor(round));let health=r<=5?1+.16*(r-1):r<=10?1.64*1.12**(r-5):r<=20?2.89*1.085**(r-10):6.54*1.045**(r-20);return {health:Math.min(14,health),speed:Math.min(1.9,(Math.min(r,10)-1)*.065+Math.max(0,r-10)*.095),damage:Math.min(2.3,1+(r-1)*.045),count:Math.min(88,6+Math.round(r*2.7)),interval:Math.max(.26,1.2-r*.044),eliteCount:r>=20?3:r>=10?2:1,stage:r<5?'OUTBREAK':r<10?'ESCALATION':r<20?'PRESSURE':r<35?'OVERRUN':'ENDURANCE'}}
